import { useDispatch } from 'react-redux';

import {
  usePageFilterApplied,
  usePageFilterData,
  usePageFilterStatus,
} from 'hooks';
import type { FilterDataStructure, FilterForm } from 'models/Filters';
import type { Dispatch } from 'redux';

import { OVERVIEW_FILTER_CONFIG } from '../../../constants';

interface UsePosToolFiltersReturn {
  applied: FilterForm;
  isGlobalZone: boolean;
  dataFilters: FilterDataStructure;
  defaults: FilterForm;
  isLoaded: boolean;
  isError: boolean;
  dispatch: Dispatch;
}

export function usePosToolFilters(): UsePosToolFiltersReturn {
  const dispatch = useDispatch();
  const { applied, isGlobalZone } = usePageFilterApplied(
    OVERVIEW_FILTER_CONFIG.pageName,
  );
  const { dataFilters, defaults } = usePageFilterData(
    OVERVIEW_FILTER_CONFIG.pageName,
  );
  const { isLoaded, isError } = usePageFilterStatus(
    OVERVIEW_FILTER_CONFIG.pageName,
  );

  return {
    applied,
    isGlobalZone,
    dataFilters,
    defaults,
    isLoaded,
    isError,
    dispatch,
  };
}
